#include "tcl.h"
#include <stdio.h>
#include <string.h>
static void hex(const char*s,int n){for(int k=0;k<n;k++)printf("%02x",(unsigned char)s[k]);}
int main(void){const char*cases[]={"set x \"","set x \"abc","set x {","set x {abc","set x [","set x [bad","set x [bad x \"abc","set x {x}tail","set x \"x\"tail","set x [bad {","set x [bad x]tail","set x \"abc\\","set x {abc\\","set x {abc\n","set x \"abc\n","\163\145\164\040\142\145\146\157\162\145\040\117\113\012\163\145\164\040\170\040\042\141\142\143","\163\145\164\040\142\145\146\157\162\145\040\117\113\073\163\145\164\040\170\040\173\141\142\143","\043\040\142\145\146\157\162\145\012\040\040\163\145\164\040\170\040\133\142\141\144","\163\145\164\040\170\040\173\170\175\164\141\151\154\073\163\145\164\040\141\146\164\145\162\040\117\113","\163\145\164\040\170\040\042\170\042\164\141\151\154\012\163\145\164\040\141\146\164\145\162\040\117\113","\163\145\164\040\170\040\042\303\251\141\142\143","\163\145\164\040\170\040\042\360\237\230\200\141\142\143","\163\145\164\040\170\040\042\377\141\142\143","\163\145\164\040\170\040\042\000\141\142\143","\163\145\164\040\170\040\042\141\142\143\000\164\141\151\154","\042","\173"};for(int k=0;k<27;k++){
Tcl_Interp*i=Tcl_CreateInterp();const char*s=cases[k];int lengths[]={24,24,21,26,26,12,14,11,11,15,1,1};int length=k<15?strlen(s):lengths[k-15];Tcl_Parse p;int offset=0,pc;while(1){pc=Tcl_ParseCommand(i,s+offset,length-offset,0,&p);if(pc!=TCL_OK||offset+p.commandSize>=length)break;int consumed=p.commandStart-s+p.commandSize;Tcl_FreeParse(&p);if(consumed<=offset){fprintf(stderr,"parser stalled");return 3;}offset=consumed;}int start=p.commandStart-s;int term=p.term-s;int size=p.commandSize;Tcl_ResetResult(i);
Tcl_Obj*v[4]={Tcl_NewStringObj("proc",4),Tcl_NewStringObj("p",1),Tcl_NewStringObj("",0),Tcl_NewStringObj(s,length)};for(int j=0;j<4;j++)Tcl_IncrRefCount(v[j]);Tcl_EvalObjv(i,4,v,TCL_EVAL_GLOBAL);int code=Tcl_EvalObjv(i,1,v+1,TCL_EVAL_GLOBAL);
Tcl_Obj*r=Tcl_GetObjResult(i);Tcl_IncrRefCount(r);int rn;const char*rs=Tcl_GetStringFromObj(r,&rn);const char*info=Tcl_GetVar(i,"errorInfo",TCL_GLOBAL_ONLY);
printf("%d\t%d\t%d\t%d\t%d\t%d\t",k,pc,start,size,term,code);hex(s,length);putchar('\t');hex(rs,rn);putchar('\t');if(info)hex(info,strlen(info));putchar('\n');Tcl_DecrRefCount(r);Tcl_FreeParse(&p);for(int j=0;j<4;j++)Tcl_DecrRefCount(v[j]);Tcl_DeleteInterp(i);
}return 0;}
